command.text:
				/* <flatten type="Javascript"> */
var f = this, g = f.grid, v = (g._language == 'v'), msg;
if (f._checked) checkPeriod(f, 'ky', g._$st);
if (f._checked) {
	f._checked = false;
	if (requestType == 0) {
		if (f.getItemValue('xtype') == '1') msg = (v ? 'Hệ thống sẽ <span class="Highlight">chỉ xóa những quyển chưa phát sinh</span>, bạn có muốn thực hiện không?' : 'The system will <span class="Highlight">only delete books that have not been created yet</span>, do you want to do so?');
		if (f.getItemValue('xtype') == '2') msg = (v ? 'Hệ thống sẽ <span class="Highlight">xóa tất cả các quyển kể cả những quyển đã phát sinh</span>, bạn có muốn thực hiện không?' : 'The system will <span class="Highlight">delete all books including those that have been created</span>. Do you want to do this?');
		$message.show(msg, 0, String.format('request(\'{0}\', true);', f.get_id()), String.format('request(\'{0}\', false);', f.get_id()));
	} else {
		f.request('VoucherBookDelete', 'VoucherBookDelete', ['ky', 'nam', ['s', 'String', g._$s], 'xtype', 'd1', 'd2']);
	}
}
/* </flatten> */

script.text:
			/* <flatten type="Javascript"> */
function init$VoucherBookTemplatesDelete$(f) {
	var g = f.grid;
	setObjectFormHidden(f, 'ky', (g._$st != '2'));
	setObjectFormHidden(f, 'd1', (g._$st == '3'));
	setObjectFormHidden(f, 'd2', (g._$st == '3'));
}
function active$VoucherBookTemplatesDelete$(f) {
	var g = f.grid, o;
	f.add_onResponseComplete(on$Filter$VoucherBookTemplatesDelete$ResponseComplete);
	f.setItemValue('ky',((g._$st != '2') ? f._p : 0));
	f.setItemValue('nam',f._y);

	o = (g._$st != '2') ? 'ky' : 'nam';
	f.getItem(o).focus();
	f.live(f.getItem(o));
}
function close$VoucherBookTemplatesDelete$(f) {try {f.remove_onResponseComplete(on$Filter$VoucherBookTemplatesDelete$ResponseComplete);} catch (ex) {}}
function on$Filter$VoucherBookTemplatesDelete$ResponseComplete(sender, e) {
	var f = e.object, g = f.grid, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'VoucherBookDelete':
			show$VoucherBookTemplatesDelete$QueryComplete(f, g, result[0][1], result[0][2]);
			break;
		default:
			break;
	}
}
function show$VoucherBookTemplatesDelete$QueryComplete(f, g, t, xtype) {
	var v = (g._language == 'v'), msg;
	requestType = 0;
	switch (t) {
		case -1:
		case 0:
			f.cancelDialog();
			msg = (v ? 'Chương trình đã thực hiện xong.' : 'The process was completed successfully.');
			$message.show(msg, String.format('refresh$Page($find(\'{0}\'));', f.get_id()));
			break;
		case 1:
			msg = (v ? 'Mã quyển đã phát sinh, không thể xóa được.' : 'Cannot delete the voucher book. It has already been used.');
			$message.show(msg, String.format('$find(\'{0}\').focus(\'{1}\');', f.get_id(), 'nam'));
			break;
		case 2:
		default:
			msg = (v ? 'Phát sinh lỗi trong quá trình thực hiện.' : 'The process was failed.');
			$message.show(msg, String.format('$find(\'{0}\').focus(\'{1}\');', f.get_id(), (g._$st != '2') ? 'ky' : 'nam'));
			break;
	}
}
var requestType = 0;
function request(id, v) {
	var f = $find(id);
	if (v) {requestType = 1; f._findButton('Ok').click();} else requestType = 0;
}
/* </flatten> */
			&OutlineEntry;
